    /**
     * Method to retrieve the Organization via an OrganizationPrimaryKey.
     * @param 	id Long
     * @return 	Organization
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Organization handle( FindOrganizationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getOrganizationId() );
    }
    
    /**
     * Method to retrieve a collection of all Organizations
     *
     * @param	query	FindAllOrganizationQuery 
     * @return 	List<Organization> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Organization> handle( FindAllOrganizationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOrganization,
 * but only if the id matches
 *
 * @param		entity	Organization
 */
	protected void emitFindOrganization( Organization entity ) {
		LOGGER.info("handling emitFindOrganization" );
		
	    queryUpdateEmitter.emit(FindOrganizationQuery.class,
	                            query -> query.getFilter().getOrganizationId().equals(entity.getOrganizationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOrganization
	 * 
	 * @param		entity	Organization
	 */
	protected void emitFindAllOrganization( Organization entity ) {
		LOGGER.info("handling emitFindAllOrganization" );
		
	    queryUpdateEmitter.emit(FindAllOrganizationQuery.class,
	                            query -> true,
	                            entity);
	}

